WITH PaymentsByOrder AS (SELECT order_id, ROUND((100 * SUM(CASE WHEN status = 'SUCCESS' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_success, SUM(CASE WHEN method = 'promptpay' THEN 1 ELSE 0 END) AS promptpay_count FROM payments WHERE amount < 430 GROUP BY order_id) SELECT o.id, o.shipping_fee, P.pct_success, P.promptpay_count FROM orders o INNER JOIN PaymentsByOrder P ON o.id = P.order_id;
